    v: [['孝', 'xiào', 'hiếu'], ['忠', 'zhōng', 'trung'], ['义', 'yì', 'nghĩa'], ['君子', 'jūnzǐ', 'quân tử'], ['小人', 'xiǎorén', 'tiểu nhân'], ['孔庙', 'Kǒngmiào', 'Khổng miếu']]
