    { t: 'mc', q: '【Trung bình】Chọn đáp án đúng.', items: [['宋代第一个专门写词的作家是：', ['柳永', '苏轼', '李清照'], 0], ['与苏轼并称“苏辛”的是：', ['辛弃疾', '陆游', '岳飞'], 0], ['元杂剧兴盛的原因之一是：', ['长期没有恢复科举，文人与民间艺术结合', '皇帝喜欢诗歌', '印刷术的发明'], 0]] },
    { t: 'fill', q: '【Trung bình】Điền tiếp câu từ.', items: [['大江东___，浪淘尽、千古风流人物。', '去'], ['江山如___，一时多少豪杰。', '画']] },
    { t: 'open', q: '【Nâng cao】Trả lời câu hỏi.', items: [['苏轼对词的发展有什么贡献？', '一是扩大了词的题材，怀古、感旧、记游、说理都能用词表达，使词成为独立的新诗体；二是改变婉约词风，开创了豪放词风。'], ['《窦娥冤》讲了一个什么故事？', '窦娥从小命苦，丈夫早死，恶棍张驴儿逼婚不成就诬告她婆婆，窦娥为保护婆婆承认罪名被判死刑，在刑场上发出感天动地的控诉，揭露了社会的黑暗。']] }
