    { t: 'mc', q: '【Trung bình】Chọn đáp án đúng.', items: [['下面哪个人物不是《西游记》里的？', ['猪八戒', '沙和尚', '诸葛亮'], 2], ['《红楼梦》的作者是：', ['曹雪芹', '吴承恩', '施耐庵'], 0], ['中国古典小说中“四大名著”不包括：', ['《三国演义》', '《水浒传》', '《聊斋志异》'], 2], ['被誉为中国封建社会百科全书的是：', ['《红楼梦》', '《史记》', '《诗经》'], 0]] },
    { t: 'open', q: '【Nâng cao】Thảo luận.', items: [['中国四大名著中，你最喜欢哪一部？为什么？', '（Tự do）Ví dụ: 《西游记》– 孙悟空勇敢机智；越南电视常播放《西游记》《三国演义》电视剧。']] }
