    v: [['茅盾', 'Máo Dùn', 'Mao Thuẫn'], ['巴金', 'Bā Jīn', 'Ba Kim'], ['老舍', 'Lǎo Shě', 'Lão Xá'], ['冰心', 'Bīng Xīn', 'Băng Tâm'], ['朱自清', 'Zhū Zìqīng', 'Chu Tự Thanh'], ['骆驼祥子', 'Luòtuo Xiángzi', 'Lạc đà Tường Tử']]
